// Verified startup gate: app logic runs only under the matching installed release.
const APP_RELEASE='6240';
// BEGIN RELEASE SCRIPTS (generated by scripts/build-release.cjs)
const RELEASE_SCRIPTS=[
  [
    "https://unpkg.com/leaflet@1.9.4/dist/leaflet.js",
    "sha256-20nQCchB9co0qIjJZRGuk2/Z9VM+kNiyxNV1lvTlZBo="
  ],
  [
    "https://unpkg.com/leaflet.markercluster@1.5.3/dist/leaflet.markercluster.js",
    "sha256-Hk4dIpcqOSb0hZjgyvFOP+cEmDXUKKNE/tT542ZbNQg="
  ],
  [
    "app.js?v=6240",
    "sha256-bHOhc+53qAgQijxWsZ5pB3+gAQRsHPkCtbWR8i0nGLU="
  ]
];
// END RELEASE SCRIPTS
let appStarted=false;
if('serviceWorker'in navigator)navigator.serviceWorker.addEventListener('message',e=>{if(e.data?.type==='RELEASE_GATE_READY')e.ports[0]?.postMessage({release:APP_RELEASE,ready:!appStarted&&e.data.release===APP_RELEASE})});
function releaseNotice(text){let el=document.getElementById('releaseStatus');if(!el){el=document.createElement('div');el.id='releaseStatus';el.setAttribute('role','status');Object.assign(el.style,{position:'fixed',inset:'20% 10% auto',padding:'24px',background:'white',color:'#123',zIndex:10000,borderRadius:'12px'});document.body.appendChild(el)}el.textContent=text}
function controllerRelease(controller){return new Promise(resolve=>{if(!controller){resolve(null);return}const channel=new MessageChannel(),timer=setTimeout(()=>{channel.port1.close();resolve(null)},1200);channel.port1.onmessage=e=>{clearTimeout(timer);channel.port1.close();resolve(e.data?.release||null)};controller.postMessage({type:'GET_RELEASE'},[channel.port2])})}
async function startRelease(){
 if(!('serviceWorker'in navigator)){releaseNotice('Diese App benötigt einen Browser mit Service-Worker-Unterstützung.');return}
 releaseNotice('App-Version wird geprüft …');
 try{
  if(await controllerRelease(navigator.serviceWorker.controller)!==APP_RELEASE){
   const registration=await navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'});
   if(!navigator.serviceWorker.controller){const ready=await Promise.race([navigator.serviceWorker.ready,new Promise((_,reject)=>setTimeout(()=>reject(Error('Installation timeout')),60000))]);if(await controllerRelease(ready.active)===APP_RELEASE){location.reload();return}}
   releaseNotice('Aktualisierung wird vorbereitet. Bitte alle alten Fenster dieser App schließen. Dieses Fenster startet danach automatisch.');
   const activate=()=>registration.waiting?.postMessage({type:'ACTIVATE_READY_GATES'});
   navigator.serviceWorker.addEventListener('controllerchange',async()=>{if(await controllerRelease(navigator.serviceWorker.controller)===APP_RELEASE)location.reload()});
   activate();setInterval(activate,3000);return;
  }
  navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).catch(()=>{});
  appStarted=true;
  for(const [src,integrity] of RELEASE_SCRIPTS)await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src=src;script.integrity=integrity;script.crossOrigin='anonymous';script.onload=resolve;script.onerror=()=>reject(Error(src));document.body.appendChild(script)});
  document.getElementById('releaseStatus')?.remove();
 }catch(error){console.error('App release:',error);releaseNotice('App-Version konnte nicht vollständig geladen werden. Bitte die Verbindung prüfen und die App erneut öffnen.');}
}
startRelease();
